</div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Batal</button><button class="btn btn-primary">Simpan Penerima</button></div></form></div></div><script>document.querySelectorAll('.modal form').forEach(form=>{if(form.dataset.calculatorReady)return;const materialCost=form.querySelector('.js-material-cost'),materialProgress=form.querySelector('.js-material-progress'),materialRemaining=form.querySelector('.js-material-remaining'),laborCost=form.querySelector('.js-labor-cost'),laborProgress=form.querySelector('.js-labor-progress'),laborRemaining=form.querySelector('.js-labor-remaining');if(!materialCost)return;const number=value=>Math.max(0,Number(String(value??'').replace(/[^0-9]/g,''))||0),format=value=>new Intl.NumberFormat('id-ID',{maximumFractionDigits:0}).format(value);const calculate=()=>{materialRemaining.value=format(number(materialCost.value)*(1-Math.min(100,number(materialProgress.value))/100));laborRemaining.value=format(number(laborCost.value)*(1-Math.min(100,number(laborProgress.value))/100))};[materialCost,materialProgress,laborCost,laborProgress].forEach(input=>input.addEventListener('input',calculate));[materialCost,laborCost].forEach(input=>input.addEventListener('blur',()=>{input.value=format(number(input.value));calculate()}));calculate();form.dataset.calculatorReady='1'});</script>
